// SPDX-License-Identifier: GPL-3.0-or-later
//! The advanced check of the spelling of the names of the nets (`PHOENIX-DRC-021`). It reads the
//! names of the nets of the board and gives to [`crate::netlint::lint_net_names`] the limits of
//! the settings (`net_name_max_len`, `net_name_autogenerated`, `net_name_pairs`); each thing the
//! lint finds is one finding at the level of `net_name_level`, written `net NAME` with the kind
//! of the issue and its detail. The check is off in the settings that come with the program.

use eh3d_phoenix_board::Board;

use super::{make, AdvancedConfig, R_NET_NAME};
use crate::netlint::{lint_net_names, NetLintConfig};
use crate::report::Report;

/// The spelling of the names of the nets (`PHOENIX-DRC-021`).
pub(super) fn net_names(board: &Board, cfg: &AdvancedConfig, out: &mut Report) {
    let Some(severity) = cfg.net_name_level else {
        return;
    };
    let names: Vec<String> = board.nets.values().map(|net| net.name.clone()).collect();
    let lint = NetLintConfig {
        max_len: usize::try_from(cfg.net_name_max_len).unwrap_or(0),
        flag_autogenerated: cfg.net_name_autogenerated,
        check_pairs: cfg.net_name_pairs,
    };
    for issue in lint_net_names(&names, &lint) {
        out.confirmed.push(
            make(&R_NET_NAME, severity, format!("net {}", issue.net)).why(&format!(
                "{}: {}",
                issue.kind.word(),
                issue.detail
            )),
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::report::Severity;
    use eh3d_phoenix_board::{Id, Net};
    use eh3d_phoenix_model::ObjectId;

    fn id(n: u32) -> Id {
        ObjectId::from_parts(1_700_000_000_000, (n & 0xfff) as u16, u64::from(n)).unwrap()
    }

    fn board_of(names: &[&str]) -> Board {
        let mut board = Board::default();
        for (n, name) in names.iter().enumerate() {
            board.nets.insert(
                id(n as u32 + 1),
                Net {
                    name: (*name).to_owned(),
                },
            );
        }
        board
    }

    fn config(text: &str) -> AdvancedConfig {
        AdvancedConfig::parse(text).unwrap()
    }

    fn run(board: &Board, cfg: &AdvancedConfig) -> Report {
        let mut out = Report::new("t");
        net_names(board, cfg, &mut out);
        out.finish();
        out
    }

    #[test]
    fn the_check_is_off_in_the_settings_that_come_with_the_program() {
        let board = board_of(&["N$1", "a b", ""]);
        assert!(run(&board, &AdvancedConfig::default()).confirmed.is_empty());
        assert!(run(&board, &config("net_name_level = off\n"))
            .confirmed
            .is_empty());
    }

    #[test]
    fn every_thing_the_lint_finds_is_a_finding_at_the_level_of_the_settings() {
        let board = board_of(&["GND", "N$12", "SIG P", "CLK_P", "gnd"]);
        let out = run(&board, &config("net_name_level = warning\n"));
        assert!(out.inconclusive.is_empty());
        let found: Vec<(&str, &str)> = out
            .confirmed
            .iter()
            .map(|f| {
                (
                    f.location.as_str(),
                    f.detail.split(':').next().unwrap_or(""),
                )
            })
            .collect();
        for expected in [
            ("net GND", "case_clash"),
            ("net gnd", "case_clash"),
            ("net N$12", "autogenerated"),
            ("net SIG P", "space"),
            ("net CLK_P", "pair_missing"),
        ] {
            assert!(found.contains(&expected), "{expected:?} in {found:?}");
        }
        for finding in &out.confirmed {
            assert_eq!(finding.code, "PHOENIX-DRC-021");
            assert_eq!(finding.severity, Severity::Warning);
            assert_eq!(finding.rule, "net_name");
        }
        let direct = lint_net_names(
            &board
                .nets
                .values()
                .map(|n| n.name.clone())
                .collect::<Vec<_>>(),
            &NetLintConfig::default(),
        );
        assert_eq!(out.confirmed.len(), direct.len());
    }

    #[test]
    fn the_limits_of_the_settings_go_to_the_lint() {
        let board = board_of(&["N$7", "ABCDEFGHIJ", "X_P"]);
        let all = run(
            &board,
            &config("net_name_level = info\nnet_name_max_len = 8\n"),
        );
        let kinds: Vec<String> = all
            .confirmed
            .iter()
            .map(|f| format!("{} {}", f.location, f.detail))
            .collect();
        assert!(
            kinds
                .iter()
                .any(|k| k.starts_with("net ABCDEFGHIJ too_long: 10 characters, at most 8")),
            "{kinds:?}"
        );
        assert!(
            kinds.iter().any(|k| k.starts_with("net N$7 autogenerated")),
            "{kinds:?}"
        );
        assert!(
            kinds.iter().any(|k| k.starts_with("net X_P pair_missing")),
            "{kinds:?}"
        );
        let quiet = run(
            &board,
            &config(
                "net_name_level = info\nnet_name_max_len = 0\nnet_name_autogenerated = off\nnet_name_pairs = off\n",
            ),
        );
        assert!(quiet.confirmed.is_empty(), "{:?}", quiet.confirmed);
    }

    #[test]
    fn the_findings_do_not_depend_on_the_order_the_nets_are_listed_in() {
        let names = ["B$1", "a", "A", "x p", "N$4", "Y_N", "y_p", "ok"];
        let cfg = config("net_name_level = error\n");
        let mut expected: Vec<(String, String)> = run(&board_of(&names), &cfg)
            .confirmed
            .iter()
            .map(|f| (f.location.clone(), f.detail.clone()))
            .collect();
        expected.sort();
        assert!(!expected.is_empty());
        // a fixed shuffle: every rotation and the reversed list
        let mut order: Vec<&str> = names.to_vec();
        for _ in 0..names.len() {
            order.rotate_left(1);
            for list in [order.clone(), order.iter().rev().copied().collect()] {
                let mut again: Vec<(String, String)> = run(&board_of(&list), &cfg)
                    .confirmed
                    .iter()
                    .map(|f| (f.location.clone(), f.detail.clone()))
                    .collect();
                again.sort();
                assert_eq!(again, expected);
            }
        }
    }
}
